metric_helper_anchor = '''def static_explanation(key: str) -> Explanation:\n'''
metric_helper = '''def metric_help(key: str) -> str:\n    """Return formula-level help for compact scorecard metrics.\n\n    This text is presentation-only. It explains values already computed by the\n    page and never recalculates projections, grades, rankings, or market logic.\n    """\n    specs = {\n        # Projection History evidence scoreboard.\n        "history_evidence_rows": (\n            "What it is: every frozen evidence row currently loaded into Projection History.\\n\\n"\n            "How it is calculated: count of rows in the durable projection evidence table (len(df)). Resolved and unresolved rows are both included.\\n\\n"\n            "How to read it: this is the size of the evidence archive, not the number of completed games."\n        ),\n        "history_resolved_games": (\n            "What it is: evidence rows where MLB has attached at least one final pitcher result.\\n\\n"\n            "How it is calculated: count(actual Ks available OR actual Hits Allowed available OR actual Outs available). A row is counted once even when all three results exist.\\n\\n"\n            "How to read it: this is the pool that can contribute to resolved diagnostics."\n        ),\n        "history_k_range_hits": (\n            "What it is: resolved strikeout results that landed inside the frozen pregame K interval.\\n\\n"\n            "How it is calculated: actual Ks must exist, both saved K range bounds must exist, and K range low ≤ actual Ks ≤ K range high.\\n\\n"\n            "How to read it: this measures interval coverage, not whether an OVER/UNDER bet won."\n        ),\n        "history_k_hit_rate": (\n            "What it is: the share of eligible resolved K intervals that contained the final strikeout total.\\n\\n"\n            "Formula: K range hits ÷ resolved rows with actual Ks + both frozen K range bounds.\\n\\n"\n            "How to read it: the saved interval is the model's central 80% range, so long-run coverage near 80% is the calibration target—not 100%."\n        ),\n        "history_hits_range_hits": (\n            "What it is: resolved Hits Allowed results inside the frozen pregame Hits interval.\\n\\n"\n            "How it is calculated: actual hits allowed and both saved Hits range bounds must exist, then low ≤ actual ≤ high.\\n\\n"\n            "How to read it: it evaluates interval coverage only; it is not sportsbook grading."\n        ),\n        "history_hits_hit_rate": (\n            "What it is: the share of eligible Hits Allowed intervals that contained the final result.\\n\\n"\n            "Formula: Hits range hits ÷ resolved rows with actual Hits Allowed + both frozen Hits range bounds.\\n\\n"\n            "How to read it: the central 80% interval should trend toward roughly 80% coverage over a large, stable sample."\n        ),\n        "history_outs_range_hits": (\n            "What it is: resolved starter-outs results inside the frozen pregame Outs interval.\\n\\n"\n            "How it is calculated: actual outs and both saved Outs range bounds must exist, then low ≤ actual ≤ high.\\n\\n"\n            "How to read it: it measures whether uncertainty was sized correctly, not a betting win/loss."\n        ),\n        "history_outs_hit_rate": (\n            "What it is: the share of eligible Outs intervals that contained the final starter-outs total.\\n\\n"\n            "Formula: Outs range hits ÷ resolved rows with actual Outs + both frozen Outs range bounds.\\n\\n"\n            "How to read it: compare it with the nominal 80% interval target; materially low coverage means the interval may be too narrow."\n        ),\n        "history_k_mae": (\n            "What it is: average absolute strikeout projection error.\\n\\n"\n            "Formula: mean(|final Ks − frozen projected Ks|) across resolved projection/result pairs. Positive and negative misses do not cancel.\\n\\n"\n            "How to read it: lower is better; 0.00 would be perfect. A value of 1.81 K means the model missed by about 1.81 strikeouts on average, regardless of direction."\n        ),\n        "history_hits_mae": (\n            "What it is: average absolute Hits Allowed projection error.\\n\\n"\n            "Formula: mean(|final Hits Allowed − frozen projected Hits Allowed|) across rows where both values exist.\\n\\n"\n            "How to read it: lower is better; this measures typical error size, not over/under bias."\n        ),\n        "history_outs_mae": (\n            "What it is: average absolute Total Outs projection error.\\n\\n"\n            "Formula: mean(|final starter outs − frozen projected outs|) across rows where both values exist.\\n\\n"\n            "How to read it: lower is better; divide by 3 if you want to think of the typical error in innings."\n        ),\n\n        # Bet Tracker summary.\n        "tracker_bets": "What it is: all saved tickets currently loaded into Bet Tracker.\\n\\nHow it is calculated: count of resolved tracker display rows, including straight bets and parlays.\\n\\nHow to read it: this is tracking volume, not a performance score.",\n        "tracker_record": "What it is: finalized WIN-LOSS-PUSH record.\\n\\nHow it is calculated: counts the tracker grading states WIN, LOSS, and PUSH/PUSH LEG after MLB results are checked. Pending/live and INVALID LINE tickets are excluded.\\n\\nHow to read it: this is result grading only and never trains the projection model.",\n        "tracker_pending": "What it is: saved tickets still waiting for a final grade, including live games.\\n\\nHow it is calculated: count of result states that are not final WIN/LOSS/PUSH/PUSH LEG/INVALID LINE.\\n\\nHow to read it: these tickets can still change and are not part of the finalized record.",\n        "tracker_net": "What it is: total tracked profit/loss in units from tickets with calculable P/L.\\n\\nHow it is calculated: sum of each saved ticket's Profit/Loss value produced from its final grade, saved stake, and saved American odds. Missing P/L values do not create assumed profit.\\n\\nHow to read it: positive is profit; negative is loss. This is tracker accounting only.",\n        "tracker_roi": "What it is: return on the stake counted by the tracker for finalized tickets.\\n\\nFormula: Net P/L ÷ total saved stake on final WIN/LOSS/PUSH rows with stake data.\\n\\nHow to read it: positive means profit relative to units risked; it is not a model probability or projection input.",\n\n        # Daily Projection Run summary.\n        "daily_projected": "What it is: starters returned in the current Daily Projection Run slate.\\n\\nHow it is calculated: number of projection rows in the selected-date slate after the batch capture/recovery path.\\n\\nHow to read it: these are the starters with a usable frozen model row on this run.",\n        "daily_new": "What it is: first-time frozen snapshots created by this run.\\n\\nHow it is calculated: count returned by the batch runner for eligible starters that did not already have the durable pregame snapshot.\\n\\nHow to read it: these are new archive writes, not duplicate projections.",\n        "daily_refreshed": "What it is: starters whose durable row already existed or was legally refreshed while still pregame.\\n\\nHow it is calculated: the batch runner's skipped/refreshed count. Frozen post-first-pitch model outputs are preserved.\\n\\nHow to read it: a high number is normal when rerunning the same slate.",\n        "daily_history_only": "What it is: starters tracked for history/context but without an eligible model snapshot in this batch.\\n\\nHow it is calculated: length of the runner's history-only list.\\n\\nHow to read it: these rows are not silently promoted into a projection.",\n        "daily_errors": "What it is: capture failures returned by the current batch run.\\n\\nHow it is calculated: number of error messages produced while loading/projecting the selected starter slate.\\n\\nHow to read it: 0 means the batch completed without recorded capture failures.",\n        "daily_confirmed": "What it is: frozen slate rows using MLB's posted batting order instead of the active-roster fallback.\\n\\nHow it is calculated: count(lineup_source == CONFIRMED_LINEUP) in the current slate.\\n\\nHow to read it: more confirmed lineups means more specific matchup context; it does not mean a bet is automatically better.",\n\n        # Top Plays summary.\n        "top_highest_probability": "What it is: the largest model hit probability among today's already-ranked Top 5 legs.\\n\\nHow it is calculated: max(Model Probability) across the five model-ranked real-line legs.\\n\\nHow to read it: it is a model probability at that exact market/line, not a guarantee and not sportsbook implied probability.",\n        "top_actionable": "What it is: Top 5 legs that clear the current straight-action gate.\\n\\nFormula: Model Probability ≥ 55% AND Data Quality ≥ 60/100.\\n\\nHow to read it: legs below either threshold stay WATCH even if they remain highly ranked.",\n        "top_decision_supported": "What it is: Top 5 legs whose settled decision-learning segment has enough favorable evidence to be labeled SUPPORTED or STRONG EVIDENCE.\\n\\nHow it is calculated: count of Decision Evidence labels in {SUPPORTED, STRONG EVIDENCE}.\\n\\nHow to read it: this is supporting accountability evidence; it does not create or reorder the projection.",\n        "top_signal_supported": "What it is: Top 5 legs with a pregame signal profile currently labeled SUPPORTED.\\n\\nHow it is calculated: count(Signal Evidence == SUPPORTED) after the board is ranked.\\n\\nHow to read it: signal evidence is descriptive safety context and cannot move today's rank by itself.",\n        "top_live_prices": "What it is: how many Top 5 legs were matched to an exact current sportsbook offer.\\n\\nHow it is calculated: count(Live Offer == True) ÷ number of ranked plays.\\n\\nHow to read it: live price availability affects execution/add-to-tracker controls, not the model-first ranking.",\n    }\n    return specs.get(\n        key,\n        "What it is: a StrikeOut King scorecard metric.\\n\\nHow it is calculated: the value comes from the page's existing read-only data path.\\n\\nHow to read it: this help layer explains the displayed value and does not change model state.",\n    )\n\n\n'''
replace_once("engine/explainability_ui.py", metric_helper_anchor, metric_helper + metric_helper_anchor)


